fn reverse(a: &mut Vec<i32>) {
    let mut left = 0;
    let mut right = a.len() as isize - 1; // Use isize for indexing

    while left < right {
        // Swap the elements at left and right indices
        a.swap(left as usize, right as usize);
        left += 1;
        right -= 1;
    }
}